action.command:
cat > /tmp/findtoken.js <<'EOF'
const fs=require("fs");
const path=require("path");
const root="/tmp/logic-extract";
// Look for the method name / FQN of githubPackagesToken referenced from any class
function walk(d){
  for(const e of fs.readdirSync(d,{withFileTypes:true})){
    const p=path.join(d,e.name);
    if(e.isDirectory()) walk(p);
    else if(e.name.endsWith(".class")){
      const buf=fs.readFileSync(p);
      if(buf.includes(Buffer.from("githubPackagesToken"))){
        console.log("TOKEN-REF in: "+p.replace(root,""));
      }
    }
  }
}
walk(root);
console.log("--- done; now listing ALL classes that reference 'maven' or 'url' or 's3' ---");
function walk2(d){
  for(const e of fs.readdirSync(d,{withFileTypes:true})){
    const p=path.join(d,e.name);
    if(e.isDirectory()) walk2(p);
    else if(e.name.endsWith(".class")){
      const buf=fs.readFileSync(p);
      if(buf.includes(Buffer.from("maven")) || buf.includes(Buffer.from("setUrl"))){
        console.log("MAVEN-REF in: "+p.replace(root,""));
      }
    }
  }
}
walk2(root);
EOF
node /tmp/findtoken.js 2>&1

